export function ManuelCabreraLogoBadge({ 
  size = "md",
  className = "" 
}: { 
  size?: "sm" | "md" | "lg" | "xl"; 
  className?: string;
}) {
  const sizeClasses = {
    sm: "w-8 h-8 p-1.5",
    md: "w-10 h-10 p-2",
    lg: "w-12 h-12 p-2.5",
    xl: "w-14 h-14 p-3",
  };

  const logoSizes = {
    sm: "w-full h-full",
    md: "w-full h-full",
    lg: "w-full h-full",
    xl: "w-full h-full",
  };

  return (
    <div className={`rounded-2xl bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 flex items-center justify-center shadow-md transition-transform duration-200 ${sizeClasses[size]} ${className}`}>
      <ManuelCabreraLogo className={`${logoSizes[size]} text-white dark:text-zinc-950`} />
    </div>
  );
}

